import{_ as e,o as t,c as i,a6 as r}from"./chunks/framework.De615z8S.js";const m=JSON.parse('{"title":"第一张可用图","description":"","frontmatter":{"id":"first-image","title":"第一张可用图","chapter":"00","status":"已公开","evidence_status":"方法已整理，未执行图像任务","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["rembg"],"order":10},"headers":[],"relativePath":"start/first-image.md","filePath":"start/first-image.md"}'),s={name:"start/first-image.md"};function o(l,a,n,d,_,c){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="第一张可用图-先完成一个任务" tabindex="-1">第一张可用图：先完成一个任务 <a class="header-anchor" href="#第一张可用图-先完成一个任务" aria-label="Permalink to &quot;第一张可用图：先完成一个任务&quot;">​</a></h1><p>准备一张清晰素材、一个明确用途、目标比例和准确文案。首次练习可以用自己拍摄的物体或虚构品牌；商品照片承担外观依据，参考图承担风格或布局依据。</p><h2 id="操作顺序" tabindex="-1">操作顺序 <a class="header-anchor" href="#操作顺序" aria-label="Permalink to &quot;操作顺序&quot;">​</a></h2><ol><li>写一句交付目标，例如“为真实收纳盒做一张书桌场景图，无文字，3:4”。</li><li>标明每张输入图的角色；列必须保留的外观与允许变化的背景。</li><li>选择工具时确认实际支持参考图、局部编辑、尺寸和导出格式；在当前入口核对，不根据模型名字推断。</li><li>使用<a href="/ai-visual-creation-handbook/prompts/P01">P01商品场景模板</a>先做一张。主体容易漂移时，改为生成背景后合成真实主体。</li><li>对照原素材检查形状、颜色、部件、配件、文字和边缘。一次只改一个关键问题。</li><li>保存原素材、实际提示词、结果和修改说明，检查实际像素与文件格式。</li></ol><h2 id="怎样判断完成" tabindex="-1">怎样判断完成 <a class="header-anchor" href="#怎样判断完成" aria-label="Permalink to &quot;怎样判断完成&quot;">​</a></h2><p>“图看起来不错”还不足以交付。商品身份、内容准确、可读文字、目标裁切和可打开文件都满足任务，才算这一张可用。没有运行结果时，只能报告方案或模板完成。</p>',6)])])}const f=e(s,[["render",o]]);export{m as __pageData,f as default};
